<?php
declare(strict_types=1);require __DIR__.'/bootstrap.php';
try{$cfg=addon_config();$nas=(string)($cfg['nas_ip']??'10.255.255.200');$db=db();$st=$db->prepare("SELECT r.username,r.framedipaddress,r.callingstationid,r.nasportid,r.acctstarttime,r.acctupdatetime,r.acctinterval,r.acctsessiontime,r.acctinputoctets,r.acctoutputoctets,c.uuid_cliente,c.nome,c.plano,c.ramal,c.cli_ativado,c.bloqueado,c.contrato FROM radacct r LEFT JOIN sis_cliente c ON LOWER(c.login)=LOWER(r.username) WHERE r.nasipaddress=? AND r.acctstoptime IS NULL ORDER BY r.acctupdatetime DESC,r.radacctid DESC");$st->bind_param('s',$nas);$st->execute();$rs=$st->get_result();$a=[];while($r=$rs->fetch_assoc())$a[]=$r;json_response(['ok'=>true,'count'=>count($a),'sessions'=>$a]);}catch(Throwable $e){json_response(['ok'=>false,'error'=>'Falha ao consultar sessões.'],500);}
